// Esta herramienta guarda un lead en Google Sheets via HTTP
// Reemplazá GOOGLE_APPS_SCRIPT_URL con tu URL real de Google Apps Script
// que reciba los datos y los escriba en tu Sheet.

const input = JSON.parse($input);

const webhookUrl = 'GOOGLE_APPS_SCRIPT_URL_AQUI';

const leadData = {
  nombre: input.nombre || 'Sin nombre',
  email: input.email || 'Sin email',
  telefono: input.telefono || 'Sin teléfono',
  consulta: input.consulta || 'Sin consulta',
  origen: input.origen || 'Asistente IA',
  estado: 'Nuevo',
  fechaHora: new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' })
};

try {
  const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(leadData)
  });
  return `Lead guardado exitosamente: ${leadData.nombre} (${leadData.email})`;
} catch (error) {
  return `Error al guardar lead: ${error.message}. Los datos del lead son: ${JSON.stringify(leadData)}`;
}

// Esta herramienta agenda una cita en Google Calendar via HTTP
// Reemplazá GOOGLE_APPS_SCRIPT_CALENDAR_URL con tu URL real

const input = JSON.parse($input);

const webhookUrl = 'GOOGLE_APPS_SCRIPT_CALENDAR_URL_AQUI';

const citaData = {
  nombre: input.nombre || 'Cliente',
  email: input.email || '',
  fecha: input.fecha,
  hora: input.hora,
  tipo: input.tipo || 'clase_prueba',
  notas: input.notas || '',
  duracion: 60
};

// Validar que la fecha sea futura
const fechaCita = new Date(`${citaData.fecha}T${citaData.hora}:00`);
const ahora = new Date();

if (fechaCita <= ahora) {
  return 'Error: La fecha y hora de la cita debe ser en el futuro. Pedile al usuario que elija otra fecha.';
}

// Validar horario (9-20hs)
const horaNum = parseInt(citaData.hora.split(':')[0]);
if (horaNum < 9 || horaNum >= 20) {
  return 'Error: El horario disponible para citas es de 9:00 a 20:00 hs. Pedile al usuario que elija un horario dentro de ese rango.';
}

try {
  const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(citaData)
  });
  return `Cita agendada exitosamente para ${citaData.nombre} el ${citaData.fecha} a las ${citaData.hora}hs. Tipo: ${citaData.tipo}.`;
} catch (error) {
  return `Error al agendar cita: ${error.message}. Datos: ${JSON.stringify(citaData)}`;
}

// Esta herramienta envía una notificación por Telegram
// Reemplazá BOT_TOKEN y CHAT_ID con tus valores reales

const input = JSON.parse($input);

const BOT_TOKEN = 'TU_BOT_TOKEN_AQUI';
const CHAT_ID = 'TU_CHAT_ID_AQUI';

const emoji = input.tipo === 'cita_agendada' ? '📅' : '🔔';
const titulo = input.tipo === 'cita_agendada' ? 'NUEVA CITA AGENDADA' : 'NUEVO LEAD';

const mensaje = `${emoji} *${titulo}*\n\n${input.resumen}\n\n🕐 _${new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' })}_\n\n🚀 ¡Respondé rápido para cerrar esta oportunidad!`;

try {
  const url = `https://api.telegram.org/bot${BOT_TOKEN}/sendMessage`;
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: CHAT_ID,
      text: mensaje,
      parse_mode: 'Markdown'
    })
  });
  const result = await response.json();
  if (result.ok) {
    return 'Notificación enviada exitosamente al dueño por Telegram.';
  } else {
    return `Error de Telegram: ${result.description}`;
  }
} catch (error) {
  return `Error al enviar notificación: ${error.message}`;
}
